# План ролика по spec закона: подача (hook) + сегменты по лекциям с ключевыми статьями (≈40% материала).
import json, sys, re
for p in sys.argv[1:]:
    s = json.load(open(p)); src = open(s['source']).read()
    title = lambda n: (re.search(r'^Статья\s+' + re.escape(n) + r'\.?\s*(.*)$', src, re.M) or [None, ''])[1].strip()
    n = len(s["lectures"]); t = 40; segs = []
    for i, L in enumerate(s['lectures'], 1):
        key = L['arts'][:max(2, (len(L['arts']) + 1) // 2)]  # примерно половина статей лекции ≈ 40% выгрузки
        d = 60 + 15 * len(key)
        segs.append(f"{i + 1}. **{L['h']} ({t // 60}:{t % 60:02d}–{(t + d) // 60}:{(t + d) % 60:02d}).** Сценка-пример из службы → стоп-кадр → плашка со статьями: " + '; '.join(f"ст. {k} «{title(k)}»" for k in key) + '. Вопрос зрителю «как правильно?» и ответ по тексту статьи.')
        t += d
    md = f"# План ролика «{s['title']}» (≈{(t + 90) // 60} мин, ≈40% материала темы)\n\n**Подача:** {s['hook']}. Каждая часть начинается с короткой сценки (как это выглядит на службе), затем — стоп-кадр с разбором, плашка с номером статьи и простым выводом «что делать сотруднику».\n\n1. **Вступление (0:00–0:40).** Зачем сотруднику ВП знать этот закон: одна яркая ситуация, где незнание закона приводит к ошибке.\n" + '\n'.join(segs) + f"\n{n + 2}. **Финал.** Короткая памятка из {n * 2} пунктов на экране и ссылка на полную выгрузку и экзамен.\n\n**Остаётся только в выгрузке:** " + ', '.join(f"ст. {k}" for k in s.get('rest', [])) + " и статьи лекций, не вошедшие в ролик.\n"
    open(f"../../content/{s['slug']}/video_plan.md", 'w').write(md); print(s['slug'], t // 60, 'мин')
